const RENTAL_SERVICE_ITEMS=[
['车辆交付','交接车辆外观、座椅、油电及随车用品，记录已有损伤并说明操作方法。'],
['常规清洁','交车前进行常规清洁；特殊污渍、吸烟或宠物清洁的费用须事先约定。'],
['保障说明','确认保单及保障范围、自负额和事故处理方式；具体保障按最终合同列示。'],
['故障协助','提供故障与事故联络方式，救援范围、可用时段及拖车费用在交付前确认。']];
const OPTIONAL_SERVICE_ITEMS=[
['额外驾驶员','登记驾驶员及有效证件，确认保险适用范围和费用。'],
['儿童座椅','确认儿童年龄、身高体重、安装方式与可用数量。'],
['额外里程','说明包含里程、超公里单价和是否存在行驶范围限制。'],
['油电补充','记录交付油电量，确认补足标准及代补服务费。'],
['雪地装备','按路线与车型确认防滑装备、安装指导和使用限制。']];
const BUSINESS_SERVICES=[
['自驾租车','车型与租期确认、交接验车、驾驶操作说明及还车结算。','油电、路桥、停车、押金与附加保障单列确认。'],
['机场接送','航班与接送点确认、人数行李核对、接机联络和点到点接送。','免费等候时长、航班延误、夜间及绕行费用提前确认。'],
['带司机包车','行程安排、车辆与司机匹配、每日用车时段和里程确认。','司机食宿、路桥停车、超时超公里按报价说明；承运安排按业务资质核对。'],
['商务接待','会议、酒店、机场等多点行程协调，明确车型、时段与开票需求。','等候、多点绕行、加班与临时变更按确认报价处理。']];
function servicePointsHTML(items){if(state.lang==='en')items=items.map(([a,b])=>[t(a),t(b)]);return `<ul class="service-points">${items.map(([title,text])=>`<li><strong>${esc(title)}</strong><span>${esc(text)}</span></li>`).join('')}</ul>`}
function businessServicesHTML(){if(state.lang==='en')return `<section class="section"><span class="eyebrow">YOUR JOURNEY, OUR SERVICE</span><h2>Four ways to travel</h2><div class="business-service-grid">${[['Self-drive rental','Vehicle handover, rental period and return settlement. Fuel, deposits and protection are confirmed separately.'],['Airport transfer','Flight, meeting point, passengers and bags. Waiting, delays and detours are quoted in advance.'],['Chauffeured trip','Vehicle, driver, itinerary and included hours and distance. Confirm operating arrangements, driver expenses and excess charges.'],['Business travel','Coordinate airport, hotel and meeting journeys. Confirm vehicle, hours, invoicing and changes.']].map(([a,b],i)=>`<article><h3>${a}</h3><p>${b}</p><a class="link" href="#/enquiry?service=${encodeURIComponent(BUSINESS_SERVICES[i][0])}">Enquire ↗</a></article>`).join('')}</div></section>`;return `<section class="section"><span class="eyebrow">YOUR JOURNEY, OUR SERVICE</span><h2>四种用车服务</h2><div class="business-service-grid">${BUSINESS_SERVICES.map(([title,include,terms])=>`<article><h3>${esc(title)}</h3><p>${esc(include)}</p><p class="muted">${esc(terms)}</p><a class="link" href="#/enquiry?service=${encodeURIComponent(title)}">咨询这项服务 ↗</a></article>`).join('')}</div></section>`}
function reviewsHTML(c){if(state.lang==='en')return `<div id="review-list" data-review-car="${c.id}" aria-live="polite"><p>Loading reviews…</p></div><details class="review-form-panel"><summary>Share your journey</summary><p>Sign in to submit. Reviews are stored for moderation before publication and are not labelled verified rentals. Do not include private contact details.</p><form onsubmit="submitVehicleReview(event,'${c.id}')"><label>Rating<select name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}">${n} stars</option>`).join('')}</select></label><label>Your experience<textarea name="content" minlength="10" maxlength="1000" required></textarea></label><label class="form-consent"><input name="consent" type="checkbox" required>I consent to review moderation and public display of my nickname and review after approval.</label><button class="btn">Submit review ↗</button><p class="form-result" role="status"></p></form></details>`;return `<div id="review-list" data-review-car="${c.id}" aria-live="polite"><p class="muted">正在读取评价…</p></div><details class="review-form-panel"><summary>分享你的旅程</summary><p class="muted">评价提交后待审核，不会立即公开或标记为已核实订单评价。请勿填写手机号、车牌等个人信息。</p><form onsubmit="submitVehicleReview(event,'${c.id}')"><label>评分<select name="rating" required>${[5,4,3,2,1].map(n=>`<option value="${n}">${n} 星</option>`).join('')}</select></label><label>旅程体验<textarea name="content" minlength="10" maxlength="1000" required placeholder="分享车辆体验、交接服务或旅程建议"></textarea></label><label class="form-consent"><input type="checkbox" name="consent" required>我同意提交此评价供审核，并在审核通过后公开展示昵称和内容。</label><button class="btn" type="submit">提交评价 ↗</button><p class="form-result" role="status"></p></form></details>`}
async function loadVehicleReviews(id){const box=document.querySelector('[data-review-car="'+id+'"]');if(!box)return;try{const data=await accountRequest('/api/reviews?car='+encodeURIComponent(id));if(!box.isConnected)return;box.innerHTML=data.reviews.length?data.reviews.map(r=>`<article class="journey-review"><strong>${esc(r.name)} · ${r.rating} / 5</strong><small>${new Date(r.created*1000).toLocaleDateString()} · 用户分享</small><p>${esc(r.content)}</p></article>`).join(''):'<p class="muted">尚无公开评价，欢迎分享你的旅程。</p>'}catch{box.textContent='暂时无法读取评价，请稍后重试。'}}
async function submitVehicleReview(event,id){event.preventDefault();const f=event.target,b=f.querySelector('button'),out=f.querySelector('.form-result');if(!state.account){out.textContent='请先登录，再提交评价。';return}b.disabled=true;try{const v=Object.fromEntries(new FormData(f));await accountRequest('/api/reviews',{method:'POST',body:JSON.stringify({car:id,rating:Number(v.rating),content:v.content,consent:v.consent==='on'})});f.reset();out.textContent='评价已保存，待审核后公开。'}catch(e){out.textContent=e.message}finally{b.disabled=false}}
function enquiryPage(){const q=new URLSearchParams(state.route.split('?')[1]||''),service=q.get('service')||'自驾租车',id=q.get('car')||'';return `<main class="page wrap enquiry-page"><div class="subhero"><span class="eyebrow">LET US PLAN YOUR DRIVE</span><h1>告诉我们你的用车安排。</h1><p>提交需求后，我们核对车辆、行程与报价。提交咨询不锁定库存，也不收取费用。</p></div><form class="enquiry-form" onsubmit="submitEnquiry(event)"><fieldset class="service-choice"><legend>服务方式</legend><div class="service-choice-grid">${BUSINESS_SERVICES.map(([s])=>`<label class="service-choice-option"><input type="radio" name="service" value="${s}" ${s===service?'checked':''} required onchange="updateEnquiryOptions(this.form)"><span>${esc(t(s))}</span></label>`).join('')}</div></fieldset><div class="form-grid"><label>车型偏好<select name="car"><option value="">请为我推荐</option>${CARS.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>服务城市<select name="city" onchange="updateEnquiryOptions(this.form)">${SERVICE_CITIES.map(c=>`<option value="${esc(c.name)}">${esc(serviceCityName(c))}</option>`).join('')}</select></label><label>人数<select name="people">${Array.from({length:60},(_,i)=>`<option value="${i+1}" ${i===1?'selected':''}>${i+1}</option>`).join('')}</select></label><label>行李件数<select name="bags" onchange="updateEnquiryOptions(this.form)">${Array.from({length:61},(_,i)=>`<option value="${i}" ${i===2?'selected':''}>${i}</option>`).join('')}</select></label><label>称呼<input name="name" maxlength="50" required autocomplete="name"></label><label>联系电话<span class="required-label">必填</span><input name="phone" type="tel" inputmode="numeric" minlength="11" maxlength="11" pattern="[0-9]{11}" title="请输入11位数字的联系电话" required autocomplete="tel" placeholder="请输入11位数字的联系电话"></label><label>微信<span class="required-label">必填</span><input name="wechat" minlength="2" maxlength="60" required autocapitalize="off" spellcheck="false" placeholder="请输入微信号"></label></div>${enquiryItineraryHTML(service)}<p class="muted">仅用于处理本次用车咨询；请勿上传身份证、驾驶证或支付信息。联系方式不公开展示。</p><label class="form-consent"><input name="consent" type="checkbox" required>我同意保存上述信息，用于联系和处理本次用车需求。</label><button class="btn" type="submit">提交用车咨询 ↗</button><p class="form-result" role="status"></p></form><section class="section"><h2>接下来会怎样</h2>${servicePointsHTML([['需求确认','核对车型、人数、行李件数与行程。'],['报价确认','明确费用、服务范围、取消规则及可用车辆。'],['预约成立','双方确认订单与合同后再安排付款和交车。']])}<p class="muted">当前为本地咨询收件功能。正式上线时需配置运营收件通知和订单后台；微信支付尚未开通。</p></section></main>`}
async function submitEnquiry(event){event.preventDefault();const f=event.target,b=f.querySelector('button[type="submit"]'),out=f.querySelector('.form-result');b.disabled=true;try{const v=Object.fromEntries(new FormData(f));const result=await accountRequest('/api/inquiries',{method:'POST',body:JSON.stringify({...v,people:Number(v.people),bags:Number(v.bags),consent:v.consent==='on'})});out.textContent='需求已保存，咨询编号：'+result.inquiry.id+'。尚未确认车辆或报价。';f.reset();updateEnquiryOptions(f)}catch(e){out.textContent=e.message}finally{b.disabled=false}}

function enquiryLocationOptions(city='成都',selected=''){const key=SERVICE_CITIES.find(c=>c.name===city)?.id;return matchPlaces().filter(p=>p.cityKey===key&&p.kind==='city').map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(matchPlaceName(p))}${p.id.startsWith('city-')?' · '+t('具体交接点确认'):''}</option>`).join('')}
function enquiryTimes(selected){return Array.from({length:48},(_,i)=>{const time=String(Math.floor(i/2)).padStart(2,'0')+':'+(i%2?'30':'00');return `<option value="${time}" ${time===selected?'selected':''}>${time}</option>`}).join('')}
function enquiryItineraryHTML(service){return `<fieldset class="enquiry-itinerary"><legend>行程安排</legend><div class="form-grid"><label>取车 / 上车地点<select name="pickupId" required>${enquiryLocationOptions()}</select></label><label>还车 / 下车地点<select name="returnId" required>${enquiryLocationOptions()}</select></label><label>目的地<select name="destinationId" required><option value="">请选择目的地</option>${matchPlaces().map(p=>`<option value="${p.id}">${esc(matchPlaceName(p))}</option>`).join('')}</select></label><label>用车天数<select name="durationDays" onchange="syncEnquiryDates(this.form,'duration')">${Array.from({length:30},(_,i)=>`<option value="${i+1}">${i+1} ${t('天')}</option>`).join('')}</select></label><label>开始日期<input type="date" name="startDate" min="${new Date().toLocaleDateString('sv-SE')}" required onchange="syncEnquiryDates(this.form,'start')"></label><label>结束日期<input type="date" name="endDate" min="${new Date().toLocaleDateString('sv-SE')}" required onchange="syncEnquiryDates(this.form,'end')"></label><label>开始时间<select name="startTime" onchange="syncEnquiryDates(this.form,'time')">${enquiryTimes('09:00')}</select></label><label>结束时间<select name="endTime" onchange="syncEnquiryDates(this.form,'time')">${enquiryTimes('18:00')}</select></label></div><p class="muted">地点来自已整理的真实城市、交通枢纽与景点；具体交接位置在报价时确认。</p></fieldset>`}
function updateEnquiryOptions(f){const city=f.elements.city.value;for(const key of ['pickupId','returnId']){const select=f.elements[key],old=select.value;select.innerHTML=enquiryLocationOptions(city,old)}syncEnquiryDates(f,'start')}
function enquiryDateString(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function syncEnquiryDates(f,source){const start=f.elements.startDate,end=f.elements.endDate,days=f.elements.durationDays,endTime=f.elements.endTime;end.setCustomValidity('');endTime.setCustomValidity('');end.min=start.value||start.min;if(!start.value)return;const startDay=new Date(start.value+'T12:00:00');if(source==='start'||source==='duration'){const next=new Date(startDay);next.setDate(next.getDate()+Number(days.value)-1);end.value=enquiryDateString(next)}if(!end.value)return;const difference=Math.round((new Date(end.value+'T12:00:00')-startDay)/86400000)+1;if(difference<1||difference>30){end.setCustomValidity(t('请选择开始日期之后、30天以内的结束日期。'));return}if(source==='end')days.value=String(difference);if(end.value===start.value&&endTime.value<=f.elements.startTime.value)endTime.setCustomValidity(t('结束时间须晚于开始时间。'))}
